    private PaymentSettings $settings;
    public function __construct(private PDO $db,private array $env=[]){$this->settings=new PaymentSettings($db,$env);}
    private function query(string $sql,array $args=[]):PDOStatement{$s=$this->db->prepare($sql);$s->execute($args);return $s;}
    private function tx(callable $fn):array{$this->db->exec('SET TRANSACTION ISOLATION LEVEL READ COMMITTED');$this->db->beginTransaction();try{if(!$this->query("SELECT id FROM jingo_catalog_locks WHERE id='catalog' FOR UPDATE")->fetchColumn())throw new HttpError(503,'Chưa cài khóa danh mục.');$r=$fn();$this->db->commit();return $r;}catch(Throwable $e){if($this->db->inTransaction())$this->db->rollBack();throw $e;}}
    public function checkout(array $in,bool $test=false,?array $context=null):array
    {
        if(array_diff(array_keys($in),['code','accessKey','email','provider'])||!is_string($in['code']??null)||!preg_match('/^J[GMCBH][A-F0-9]{10}$/D',$in['code'])||!in_array($in['provider']??null,['SEPAY_CARD'],true)||array_key_exists('accessKey',$in)&&(!is_string($in['accessKey'])||!preg_match('/^[a-f0-9]{64}$/D',$in['accessKey']))||array_key_exists('email',$in)&&(!is_string($in['email'])||strlen($in['email'])>200||!filter_var($in['email'],FILTER_VALIDATE_EMAIL)))throw new HttpError(400,'Kiểm tra mã đơn, khóa/email và cổng thanh toán.');if($context!==null&&($test||!str_starts_with($in['code'],'JC')))throw new HttpError(400,'Chỉ thanh toán giỏ CTV LIVE.');if(!$test&&$context===null&&!isset($in['accessKey'])&&!isset($in['email']))throw new HttpError(400,'Nhập khóa hoặc email tra cứu.');if($test&&(str_starts_with($in['code'],'JB')||str_starts_with($in['code'],'JH')))throw new HttpError(400,'TEST dùng vé đơn hoặc giỏ vé web.');
        return $this->tx(function()use($in,$test,$context){$c=$this->settings->config();if($c['mode']!==($test?'TEST':'LIVE')||!SepayCardSettings::ready($c))throw new HttpError(400,'Cổng chưa bật hoặc đang ở môi trường khác.');$base=$this->settings->base();if(!$test&&!str_starts_with($base,'https://'))throw new HttpError(503,'Thanh toán LIVE cần HTTPS.');if($context!==null)(new PaymentTargets($this->db))->authorizeContext($in,$context);elseif(!$test)(new PaymentTargets($this->db))->authorizeCode($in);$s=(new PaymentTargets($this->db))->state($in['code'],$context);$config=['merchant'=>$c['sepayMerchantId'],'secret'=>$c['sepayCardEncrypted'],'ipnKey'=>$c['sepayCardIpnEncrypted']];if(isset($s['hotel']))$config['hotelId']=$s['hotel']['row']['id'];elseif($s['bundle'])$config['bundleId']=$s['bundle']['id'];elseif($s['cart'])$config+=['cartId'=>$s['cart']['id'],'cartOrders'=>array_map(fn($o)=>['id'=>$o['id'],'amount'=>json_decode($o['snapshot'],true,512,JSON_THROW_ON_ERROR)['total']],$s['orders']),'channel'=>$s['cart']['channel'],'partnerId'=>$s['cart']['partner_id'],'counterId'=>$s['cart']['counter_id']];$orderId=$s['orders'][0]['id']??null;$q=$this->query("SELECT * FROM jingo_gateway_attempts WHERE provider='SEPAY_CARD' AND mode=? AND config_version=? AND amount=? AND status='PENDING' AND expires_at>UTC_TIMESTAMP(6) ORDER BY created_at DESC,id DESC",[$c['mode'],$c['version'],$s['amount']]);$attempt=null;while($r=$q->fetch(PDO::FETCH_ASSOC))if($r['order_id']===$orderId&&json_decode($r['config'],true,512,JSON_THROW_ON_ERROR)===$config){$attempt=$r;break;}if(!$attempt){$id='JMP'.strtoupper(bin2hex(random_bytes(12)));$this->query("INSERT INTO jingo_gateway_attempts(id,order_id,provider,mode,amount,config_version,config,expires_at) VALUES (?,?,'SEPAY_CARD',?,?,?,?,DATE_ADD(UTC_TIMESTAMP(6),INTERVAL 15 MINUTE))",[$id,$orderId,$c['mode'],$s['amount'],$c['version'],json_encode($config,JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR)]);$attempt=$this->query('SELECT * FROM jingo_gateway_attempts WHERE id=?',[$id])->fetch(PDO::FETCH_ASSOC);}$form=SepayCardProtocol::form($c['mode'],$config['merchant'],(new SecretCipher(OrderMail::directory()))->decrypt($config['secret']),$attempt['id'],$in['code'],$s['amount'],$base);return ['id'=>$attempt['id'],'provider'=>'SEPAY_CARD','mode'=>$c['mode'],'amount'=>$s['amount'],'expiresAt'=>$attempt['expires_at'],'form'=>$form];});
    }
    public function ipn(mixed $body,string $key):array
    {
        $c=$this->settings->config();$credential=$c['sepayCardIpnEncrypted']??'';
        if($credential===''||!hash_equals((new SecretCipher(OrderMail::directory()))->decrypt($credential),$key))throw new HttpError(401,'IPN authentication failed');
        try{$p=SepayCardProtocol::notification($body);}catch(InvalidArgumentException){throw new HttpError(400,'Invalid card IPN payload');}
        $a=$this->query("SELECT * FROM jingo_gateway_attempts WHERE id=? AND provider='SEPAY_CARD'",[$p['invoice']])->fetch(PDO::FETCH_ASSOC);
        if(!$a)return $this->tx(function()use($c,$p){$id='SEPAY_CARD:'.$c['mode'].':'.$p['external'];$prior=$this->query('SELECT fingerprint FROM jingo_gateway_events WHERE id=?',[$id])->fetchColumn();if($prior!==false&&!hash_equals($prior,$p['fingerprint']))throw new HttpError(409,'Giao dịch đã nhận với dữ liệu khác.');$this->query("INSERT INTO jingo_gateway_events(id,provider,mode,amount,status,reason,fingerprint) VALUES (?,'SEPAY_CARD',?,?,'REVIEW',?,?) ON DUPLICATE KEY UPDATE id=id",[$id,$c['mode'],$p['amount'],'Không tìm thấy yêu cầu thanh toán thẻ.',$p['fingerprint']]);return ['success'=>true];});
        $this->settle($a,$p['external'],$p['amount'],$p['fingerprint'],$p['reason'],$credential);return ['success'=>true];
    }
    public function returnPath(?array $query):string
    {
        $id=$query['order_invoice_number']??'';if(is_string($id)&&preg_match('/^JMP[A-F0-9]{24}$/D',$id)){$config=$this->query("SELECT config FROM jingo_gateway_attempts WHERE id=? AND provider='SEPAY_CARD'",[$id])->fetchColumn();if($config)return PaymentTargets::returnPath(json_decode($config,true,512,JSON_THROW_ON_ERROR));}return '/tra-cuu?gateway=return';
    }
    private function settle(array $original,string $external,int $amount,string $fingerprint,string $reason='',string $credential=''):array
    {
        return $this->tx(function()use($original,$external,$amount,$fingerprint,$reason,$credential){$id='SEPAY_CARD:'.$original['mode'].':'.$external;$prior=$this->query('SELECT status,fingerprint FROM jingo_gateway_events WHERE id=?',[$id])->fetch(PDO::FETCH_ASSOC);if($prior){if(!hash_equals($prior['fingerprint'],$fingerprint))throw new HttpError(409,'Giao dịch đã nhận với dữ liệu khác.');return ['duplicate'=>true,'status'=>$prior['status']];}$a=$this->query('SELECT * FROM jingo_gateway_attempts WHERE id=? FOR UPDATE',[$original['id']])->fetch(PDO::FETCH_ASSOC);$config=json_decode($a['config'],true,512,JSON_THROW_ON_ERROR);$this->query("INSERT INTO jingo_gateway_events(id,attempt_id,order_id,provider,mode,amount,status,reason,fingerprint) VALUES (?,?,?,'SEPAY_CARD',?,?,'REVIEW','Đang xử lý',?)",[$id,$a['id'],$a['order_id'],$a['mode'],$amount,$fingerprint]);$s=null;try{if(isset($config['hotelId'])){$code=$this->query('SELECT code FROM jingo_stay_bookings WHERE id=?',[$config['hotelId']])->fetchColumn();if(!$code)throw new HttpError(409,'Không tìm thấy đơn phòng.');$s=(new PaymentTargets($this->db))->state($code,PaymentTargets::context($config));}elseif(isset($config['bundleId'])){$b=$this->query('SELECT code FROM jingo_checkout_bundles WHERE id=?',[$config['bundleId']])->fetchColumn();if(!$b)throw new HttpError(409,'Mã tổng không còn hợp lệ.');$s=(new PaymentTargets($this->db))->state($b,PaymentTargets::context($config));}elseif(isset($config['cartId'])){$code=$this->query('SELECT code FROM jingo_carts WHERE id=?',[$config['cartId']])->fetchColumn();if(!$code)throw new HttpError(409,'Giỏ không còn hợp lệ.');$s=(new PaymentTargets($this->db))->state($code,PaymentTargets::context($config));$currentTargets=array_map(fn($o)=>['id'=>$o['id'],'amount'=>json_decode($o['snapshot'],true,512,JSON_THROW_ON_ERROR)['total']],$s['orders']);if($currentTargets!==$config['cartOrders'])$reason='Thành phần giỏ đã thay đổi.';}else{$code=$this->query('SELECT code FROM jingo_orders WHERE id=?',[$a['order_id']])->fetchColumn();if(!$code)throw new HttpError(409,'Đơn không còn hợp lệ.');$s=(new PaymentTargets($this->db))->state($code,PaymentTargets::context($config));}}catch(HttpError $e){$reason=$reason?:$e->getMessage();}if(!$s||$s['amount']!==$amount||(int)$a['amount']!==$amount)$reason=$reason?:'Số tiền không khớp.';if(strtotime($a['expires_at'].' UTC')<=time())$reason='Yêu cầu đã hết hạn; cần đối soát thủ công.';$current=$this->settings->config();if($current['mode']!==$a['mode']||!$current['sepayCardEnabled'])$reason='Cổng đã tắt hoặc đổi môi trường.';elseif(($current['sepayCardEncrypted']??null)!==$config['secret']||$current['sepayMerchantId']!==$config['merchant']||($current['sepayCardIpnEncrypted']??null)!==$config['ipnKey']||$credential!==($current['sepayCardIpnEncrypted']??null))$reason='Cấu hình thẻ SePay đã thay đổi; cần đối soát thủ công.';if($this->query('SELECT reference_hash FROM jingo_payment_references WHERE reference_hash=?',[hash('sha256',$id)])->fetchColumn())$reason='Giao dịch đã có trong sổ thu.';$status=$reason!==''?'REVIEW':($a['mode']==='TEST'?'TEST':'PAID');if($status==='PAID')(new PaymentTargets($this->db))->credit($s,$id,'SEPAY_CARD');if(isset($config['hotelId'])&&$this->query('SELECT id FROM jingo_stay_bookings WHERE id=?',[$config['hotelId']])->fetchColumn())$this->query('INSERT INTO jingo_stay_payment_events(event_id,booking_id) VALUES (?,?)',[$id,$config['hotelId']]);$this->query('UPDATE jingo_gateway_events SET status=?,reason=? WHERE id=?',[$status,$reason,$id]);$this->query("UPDATE jingo_gateway_attempts SET status=? WHERE id=? AND status<>'PAID'",[$status,$a['id']]);return ['duplicate'=>false,'status'=>$status];});
    }
}
